import { AlertCircle, Boxes, Building2, Edit, Loader2, MapPin, Plus, RefreshCw, Ruler, Search, Trash2, Users } from "lucide-react";
import { createLocation, createParty, createProduct, createUom, createPosBarcode, createPosPrice, createTaxCode, deactivatePosBarcode, deactivatePosPrice, deleteLocation, deleteParty, deleteProduct, deleteUom, getLocations, getParties, getPosBarcodes, getPosPrices, getProductCategories, getProducts, getReturnPolicy, getUoms, getTaxActivationPrecheck, getTaxCodes, getTaxSettings, updateProductTaxCode, updateTaxCode, updateTaxSettings, updateBusinessFeatures, updateBusinessProfile, updateLocation, setDefaultLocation, updateParty, updatePosPrice, updateProduct, updateReturnPolicy, updateUom } from "@/api/client";
