type AnyRecord = Record<string, any>;
type TabKey = "parties" | "locations" | "uoms" | "products";
type Mode = "create" | "edit";

function normalizeArray(data:any,keys:string[]){ for(const key of keys){ if(Array.isArray(data?.[key])) return data[key]; } if(Array.isArray(data?.data)) return data.data; if(Array.isArray(data)) return data; return []; }
function formatDateTime(value:unknown){ if(!value) return "-"; const date=new Date(String(value)); return Number.isNaN(date.getTime())?String(value):date.toLocaleString(); }
function boolText(value:unknown){ return value ? "Yes" : "No"; }
function getErrorMessage(error:unknown){ const err=error as {response?:{data?:{message?:string;error?:string;detail?:string}};message?:string}; return err?.response?.data?.message || err?.response?.data?.error || err?.response?.data?.detail || err?.message || "Action failed. Please try again."; }

const emptyParty={party_type:"CUSTOMER",party_name:"",phone:"",email:"",tax_id:"",billing_address:"",shipping_address:"",is_active:"true"};
const emptyLocation={location_code:"",location_name:"",location_type:"WAREHOUSE",is_active:"true",is_saleable:"true",is_stock_holding:"true",address:"",phone:"",email:"",notes:""};
const emptyUom={uom_code:"",uom_name:""};
const emptyProduct={sku:"",product_name:"",description:"",product_type:"RAW",uom_code:"KG",category_id:"",tax_code_id:"",is_purchasable:"true",is_stock_item:"true",lot_prefix:"",track_lots:"true",track_expiry:"false",shelf_life_days:"",is_saleable:"true",is_active:"true"};

export default function Setup(){
  const [activeTab,setActiveTab]=useState<TabKey>("parties");
  const [search,setSearch]=useState("");
  const [lastRefreshed,setLastRefreshed]=useState<Date|null>(null);
  const [dialogTab,setDialogTab]=useState<TabKey|null>(null);
  const [mode,setMode]=useState<Mode>("create");
  const [editId,setEditId]=useState("");
  const [partyForm,setPartyForm]=useState(emptyParty);
  const [locationForm,setLocationForm]=useState(emptyLocation);
  const [uomForm,setUomForm]=useState(emptyUom);
  const [productForm,setProductForm]=useState(emptyProduct);
  const { data: businessProfile, refetch: refetchBusinessProfile } = useBusinessProfile();
  const businessFeatures = useBusinessFeatures();
  const [profileForm,setProfileForm]=useState(BUSINESS_PROFILE_FALLBACK);
  useEffect(()=>setProfileForm(businessProfile),[businessProfile]);
  const partiesQuery=useQuery({queryKey:["setup-parties"],queryFn:getParties});
  const locationsQuery=useQuery({queryKey:["setup-locations"],queryFn:getLocations});
  const uomsQuery=useQuery({queryKey:["setup-uoms"],queryFn:getUoms});
  const productsQuery=useQuery({queryKey:["setup-products"],queryFn:getProducts});
  const categoriesQuery=useQuery({queryKey:["setup-product-categories"],queryFn:getProductCategories});
  const taxCodesQuery=useQuery({queryKey:["setup-tax-codes"],queryFn:getTaxCodes});
  const parties:AnyRecord[]=normalizeArray(partiesQuery.data,["parties","data"]);
  const locations:AnyRecord[]=normalizeArray(locationsQuery.data,["locations","data"]);
  const uoms:AnyRecord[]=normalizeArray(uomsQuery.data,["uoms","data"]);
  const products:AnyRecord[]=normalizeArray(productsQuery.data,["products","data"]);
  const categories:AnyRecord[]=normalizeArray(categoriesQuery.data,["categories","data"]);
  const taxCodes:AnyRecord[]=normalizeArray(taxCodesQuery.data,["tax_codes","data"]);
  async function refresh(tab?:TabKey){ await Promise.all((tab?[tab]:["parties","locations","uoms","products"] as TabKey[]).map(t=> t==="parties"?partiesQuery.refetch():t==="locations"?locationsQuery.refetch():t==="uoms"?uomsQuery.refetch():productsQuery.refetch())); setLastRefreshed(new Date()); }
  const closeDialog=()=>{setDialogTab(null);setMode("create");setEditId("");};
  const createPartyMutation=useMutation({mutationFn:createParty,onSuccess:async()=>{await refresh("parties");closeDialog();}});
  const updatePartyMutation=useMutation({mutationFn:({id,payload}:{id:string;payload:any})=>updateParty(id,payload),onSuccess:async()=>{await refresh("parties");closeDialog();}});
  const deletePartyMutation=useMutation({mutationFn:deleteParty,onSuccess:async()=>refresh("parties")});
  const createLocationMutation=useMutation({mutationFn:createLocation,onSuccess:async()=>{await refresh("locations");closeDialog();}});
  const updateLocationMutation=useMutation({mutationFn:({id,payload}:{id:string;payload:any})=>updateLocation(id,payload),onSuccess:async()=>{await refresh("locations");closeDialog();}});
  const defaultLocationMutation=useMutation({mutationFn:setDefaultLocation,onSuccess:async()=>refresh("locations")});
  const deleteLocationMutation=useMutation({mutationFn:deleteLocation,onSuccess:async()=>refresh("locations")});
  const createUomMutation=useMutation({mutationFn:createUom,onSuccess:async()=>{await refresh("uoms");closeDialog();}});
  const updateUomMutation=useMutation({mutationFn:({id,payload}:{id:string;payload:any})=>updateUom(id,payload),onSuccess:async()=>{await refresh("uoms");closeDialog();}});
  const deleteUomMutation=useMutation({mutationFn:deleteUom,onSuccess:async()=>refresh("uoms")});
  const createProductMutation=useMutation({mutationFn:createProduct,onSuccess:async()=>{await refresh("products");closeDialog();}});
  const updateProductMutation=useMutation({mutationFn:({id,payload}:{id:string;payload:any})=>updateProduct(id,payload),onSuccess:async()=>{await refresh("products");closeDialog();}});
  const deleteProductMutation=useMutation({mutationFn:deleteProduct,onSuccess:async()=>refresh("products")});
  const profileMutation=useMutation({mutationFn:updateBusinessProfile,onSuccess:async()=>{await refetchBusinessProfile();}});
  const featureMutation=useMutation({mutationFn:updateBusinessFeatures,onSuccess:async()=>{await businessFeatures.refetch();}});
  const currentRows=useMemo(()=> activeTab==="parties"?parties:activeTab==="locations"?locations:activeTab==="uoms"?uoms:products,[activeTab,parties,locations,uoms,products]);
  const filteredRows=useMemo(()=>{const term=search.trim().toLowerCase(); if(!term) return currentRows; return currentRows.filter((row:AnyRecord)=>Object.values(row).join(" ").toLowerCase().includes(term));},[currentRows,search]);
  const loading=partiesQuery.isLoading||locationsQuery.isLoading||uomsQuery.isLoading||productsQuery.isLoading;
  const hasError=partiesQuery.isError||locationsQuery.isError||uomsQuery.isError||productsQuery.isError;
  const actionError=createPartyMutation.error||updatePartyMutation.error||deletePartyMutation.error||createLocationMutation.error||updateLocationMutation.error||defaultLocationMutation.error||deleteLocationMutation.error||createUomMutation.error||updateUomMutation.error||deleteUomMutation.error||createProductMutation.error||updateProductMutation.error||deleteProductMutation.error||profileMutation.error||featureMutation.error;
  function openCreate(){ setMode("create"); setEditId(""); setPartyForm(emptyParty); setLocationForm(emptyLocation); setUomForm(emptyUom); setProductForm(emptyProduct); setDialogTab(activeTab); }
  function openEdit(tab:TabKey,row:AnyRecord){ setMode("edit"); setDialogTab(tab); if(tab==="parties"){setEditId(row.party_id);setPartyForm({party_type:row.party_type||"CUSTOMER",party_name:row.party_name||"",phone:row.phone||"",email:row.email||"",tax_id:row.tax_id||"",billing_address:row.billing_address||"",shipping_address:row.shipping_address||"",is_active:String(row.is_active!==false)});} if(tab==="locations"){setEditId(row.location_id);setLocationForm({location_code:row.location_code||"",location_name:row.location_name||"",location_type:row.location_type||"WAREHOUSE",is_active:String(row.is_active!==false),is_saleable:String(row.is_saleable!==false),is_stock_holding:String(row.is_stock_holding!==false),address:row.address||"",phone:row.phone||"",email:row.email||"",notes:row.notes||""});} if(tab==="uoms"){setEditId(row.uom_code);setUomForm({uom_code:row.uom_code||"",uom_name:row.uom_name||""});} if(tab==="products"){setEditId(row.product_id);setProductForm({sku:row.sku||"",product_name:row.product_name||"",description:row.description||"",product_type:row.product_type||"RAW",uom_code:row.uom_code||"KG",category_id:row.category_id||"",tax_code_id:row.tax_code_id||"",is_purchasable:String(row.is_purchasable!==false),is_stock_item:String(row.is_stock_item!==false),lot_prefix:row.lot_prefix||"",track_lots:String(row.track_lots!==false),track_expiry:String(row.track_expiry===true),shelf_life_days:row.shelf_life_days?String(row.shelf_life_days):"",is_saleable:String(row.is_saleable!==false),is_active:String(row.is_active!==false)});} }
  function currentLabel(){return activeTab==="parties"?"New Party":activeTab==="locations"?"New Location":activeTab==="uoms"?"New UOM":"New Product";}
  function save(){ if(dialogTab==="parties"){const payload={...partyForm,is_active:partyForm.is_active==="true"}; return mode==="edit"?updatePartyMutation.mutate({id:editId,payload}):createPartyMutation.mutate(payload);} if(dialogTab==="locations"){const payload={...locationForm,is_active:locationForm.is_active==="true",is_saleable:locationForm.is_saleable==="true",is_stock_holding:locationForm.is_stock_holding==="true"}; return mode==="edit"?updateLocationMutation.mutate({id:editId,payload}):createLocationMutation.mutate(payload);} if(dialogTab==="uoms"){return mode==="edit"?updateUomMutation.mutate({id:editId,payload:{uom_name:uomForm.uom_name}}):createUomMutation.mutate(uomForm);} if(dialogTab==="products"){const payload={...productForm,category_id:productForm.category_id||null,tax_code_id:productForm.tax_code_id||null,track_lots:productForm.track_lots==="true",track_expiry:productForm.track_expiry==="true",shelf_life_days:productForm.shelf_life_days?Number(productForm.shelf_life_days):null,is_saleable:productForm.is_saleable==="true",is_purchasable:productForm.is_purchasable==="true",is_stock_item:productForm.is_stock_item==="true",is_active:productForm.is_active==="true",lot_prefix:productForm.lot_prefix||null}; return mode==="edit"?updateProductMutation.mutate({id:editId,payload}):createProductMutation.mutate(payload);} }
  function remove(tab:TabKey,row:AnyRecord){ if(tab==="locations"){window.alert("Locations cannot be deleted. Edit the location and mark it inactive instead.");return;} const label=tab==="parties"?row.party_name:tab==="uoms"?row.uom_code:row.product_name; if(!window.confirm(`Delete ${label}? If it is already used, the system will block deletion. Deactivation is safer for used records.`)) return; if(tab==="parties") deletePartyMutation.mutate(row.party_id); if(tab==="uoms") deleteUomMutation.mutate(row.uom_code); if(tab==="products") deleteProductMutation.mutate(row.product_id); }
  if(loading) return <div className="flex h-80 items-center justify-center"><Loader2 className="h-8 w-8 animate-spin text-slate-500" /></div>;
  // @ts-ignore Profile field list intentionally excludes read-only currency_code.
  if(hasError) return <Alert variant="destructive"><AlertTitle>Setup failed to load</AlertTitle><AlertDescription>{getErrorMessage(partiesQuery.error||locationsQuery.error||uomsQuery.error||productsQuery.error)}</AlertDescription></Alert>;
  return <div className="space-y-6"><div className="flex flex-col justify-between gap-4 md:flex-row md:items-center"><div><h1 className="text-3xl font-bold tracking-tight">Setup</h1><p className="mt-1 text-slate-500">Manage master data used across purchasing, inventory, sales, and finance.</p></div><div className="flex flex-wrap gap-3"><Button variant="outline" onClick={()=>refresh()}><RefreshCw className="mr-2 h-4 w-4" />Refresh</Button><Can roles={ACTION_ROLES.CREATE_SETUP}><Button onClick={openCreate}><Plus className="mr-2 h-4 w-4" />{currentLabel()}</Button></Can></div></div>{lastRefreshed&&<p className="text-xs text-slate-500">Last refreshed: {lastRefreshed.toLocaleTimeString()}</p>}{actionError&&<Alert variant="destructive"><AlertCircle className="h-4 w-4"/><AlertTitle>Setup action failed</AlertTitle><AlertDescription>{getErrorMessage(actionError)}</AlertDescription></Alert>}<BusinessFeaturesPanel query={businessFeatures} mutation={featureMutation}/><Can roles={ACTION_ROLES.ASSIGN_ROLE}><BranchAccessPanel/></Can><Card className="rounded-2xl shadow-sm"><CardHeader><CardTitle className="flex items-center gap-2"><Building2 className="h-5 w-5" />Business Profile</CardTitle><p className="text-sm text-slate-500">Configure the business identity used in the application and formal documents.</p></CardHeader><CardContent><div className="grid gap-4 md:grid-cols-2">{([['company_name','Company Name'],['business_name','Business Name'],['business_type','Business Type'],['phone','Phone'],['email','Email'],['address','Address'],['logo_path','Logo Path / Logo URL'],['timezone','Timezone']] as const).map(([field,label])=><FormInput key={field} label={label} value={profileForm[field] || ''} disabled={field==='currency_code'} onChange={value=>setProfileForm({...profileForm,[field]:value})}/>)}</div><div className="mt-4 flex items-center justify-between"><p className="text-sm text-slate-500">Currency: <span className="font-medium text-slate-900">{businessProfile.currency_code}</span> (read-only)</p><Can roles={ACTION_ROLES.EDIT_SETUP}><Button onClick={()=>profileMutation.mutate({company_name:profileForm.company_name,business_name:profileForm.business_name,business_type:profileForm.business_type,phone:profileForm.phone,email:profileForm.email,address:profileForm.address,logo_path:profileForm.logo_path,timezone:profileForm.timezone})} disabled={profileMutation.isPending}>{profileMutation.isPending?'Saving...':'Save Business Profile'}</Button></Can></div></CardContent></Card><div className="grid gap-4 md:grid-cols-4"><SetupTab active={activeTab==="parties"} icon={Users} title="Parties" count={parties.length} onClick={()=>{setActiveTab("parties");setSearch("");}}/><SetupTab active={activeTab==="locations"} icon={MapPin} title="Locations" count={locations.length} onClick={()=>{setActiveTab("locations");setSearch("");}}/><SetupTab active={activeTab==="uoms"} icon={Ruler} title="Units" count={uoms.length} onClick={()=>{setActiveTab("uoms");setSearch("");}}/><SetupTab active={activeTab==="products"} icon={Boxes} title="Products" count={products.length} onClick={()=>{setActiveTab("products");setSearch("");}}/></div><Card className="rounded-2xl shadow-sm"><CardHeader className="space-y-4"><CardTitle className="flex items-center gap-2"><Building2 className="h-5 w-5" />{activeTab==="parties"&&"Parties"}{activeTab==="locations"&&"Locations"}{activeTab==="uoms"&&"Units of Measure"}{activeTab==="products"&&"Products"}</CardTitle><div className="relative max-w-xl"><Search className="absolute left-3 top-2.5 h-4 w-4 text-slate-400"/><Input placeholder="Search setup records..." className="pl-9" value={search} onChange={e=>setSearch(e.target.value)}/></div></CardHeader><CardContent>{activeTab==="locations"&&<div className="mb-4 flex flex-col gap-2 sm:flex-row sm:items-center"><span className="text-sm font-medium">Default operating location</span><Select value={locationsQuery.data?.default_location_id||""} onValueChange={value=>defaultLocationMutation.mutate(value)}><SelectTrigger className="max-w-md"><SelectValue placeholder="Choose the business default"/></SelectTrigger><SelectContent>{locations.filter((location:any)=>location.is_active).map((location:any)=><SelectItem key={location.location_id} value={location.location_id}>{location.location_name} ({location.location_code})</SelectItem>)}</SelectContent></Select><span className="text-xs text-slate-500">50 active non-system locations by default</span></div>}<SetupTable tab={activeTab} rows={filteredRows} onOpen={(row)=>openEdit(activeTab,row)} onDelete={(row)=>remove(activeTab,row)}/></CardContent></Card><Dialog open={!!dialogTab} onOpenChange={(open)=>!open&&closeDialog()}><DialogContent className="max-h-[90vh] w-[95vw] !max-w-[900px] overflow-y-auto"><DialogHeader><DialogTitle>{mode==="edit"?"Edit":"New"} {dialogTab==="parties"?"Party":dialogTab==="locations"?"Location":dialogTab==="uoms"?"Unit of Measure":"Product"}</DialogTitle></DialogHeader>{dialogTab==="parties"&&<PartyForm form={partyForm} setForm={setPartyForm}/>} {dialogTab==="locations"&&<LocationForm form={locationForm} setForm={setLocationForm}/>} {dialogTab==="uoms"&&<UomForm form={uomForm} setForm={setUomForm} editing={mode==="edit"}/>} {dialogTab==="products"&&<ProductForm form={productForm} setForm={setProductForm} uoms={uoms}/>}<div className="flex justify-end gap-3 border-t pt-4"><Button variant="outline" onClick={closeDialog}>Close</Button><Can roles={mode==="edit"?ACTION_ROLES.EDIT_SETUP:ACTION_ROLES.CREATE_SETUP}><Button onClick={save}> {mode==="edit"?"Save Changes":"Save"}</Button></Can></div></DialogContent></Dialog></div>;
}
function ProductPricesPanel({query,profile,onCreate,onUpdate,onDeactivate}:{query:any;profile:any;onCreate:(payload:any)=>void;onUpdate:(payload:any)=>void;onDeactivate:(id:string)=>void}){
  const rows=query.data?.prices || query.data?.data || [];
  const [search,setSearch]=useState("");
  const [drafts,setDrafts]=useState<Record<string,string>>({});
  const [taxDrafts,setTaxDrafts]=useState<Record<string,string>>({});
  const queryClient=useQueryClient();
  const codesQuery=useQuery({queryKey:["selling-price-tax-codes"],queryFn:getTaxCodes});
  const taxMutation=useMutation({mutationFn:({id,taxCodeId}:{id:string;taxCodeId:string|null})=>updateProductTaxCode(id,taxCodeId),onSuccess:async()=>{setTaxDrafts({});await query.refetch();await queryClient.invalidateQueries({queryKey:["setup-products"]});await queryClient.invalidateQueries({queryKey:["tax-product-classification"]});await queryClient.invalidateQueries({queryKey:["pos-products"]});await queryClient.invalidateQueries({queryKey:["tax-activation-precheck"]});}});
  const today=new Date().toISOString().slice(0,10);
  const codes=normalizeArray(codesQuery.data,["tax_codes","data"]).filter((code:any)=>code.is_active!==false && String(code.effective_from).slice(0,10)<=today && (!code.effective_to || String(code.effective_to).slice(0,10)>=today));
  const visible=rows.filter((row:any)=>!search.trim() || `${row.sku} ${row.product_name}`.toLowerCase().includes(search.trim().toLowerCase()));
  const label=(code:any)=>code?.treatment === "STANDARD" ? `${code.name || "Standard Rated VAT"} — ${code.rate}%` : code?.treatment === "ZERO_RATED" ? `${code.name || "Zero Rated"} — 0%` : code?.name || (code?.treatment === "EXEMPT" ? "Exempt" : code?.treatment === "OUT_OF_SCOPE" ? "Out of Scope" : "Not classified");
  return <Card className="rounded-2xl shadow-sm"><CardHeader><CardTitle>Product Prices</CardTitle><p className="text-sm text-slate-500">Manage server-authoritative POS selling prices and product tax treatment in {profile.currency_code}. Tax treatment remains owned by the product master.</p><Input placeholder="Search products by SKU or name..." value={search} onChange={e=>setSearch(e.target.value)}/></CardHeader><CardContent><div className="overflow-x-auto rounded-xl border"><Table><TableHeader><TableRow><TableHead>SKU</TableHead><TableHead>Product</TableHead><TableHead>Current Selling Price</TableHead><TableHead>Tax Treatment</TableHead><TableHead>Currency</TableHead><TableHead>Status</TableHead><TableHead className="text-right">Action</TableHead></TableRow></TableHeader><TableBody>{query.isLoading?<TableRow><TableCell colSpan={7} className="h-20 text-center">Loading prices...</TableCell></TableRow>:visible.length===0?<TableRow><TableCell colSpan={7} className="h-20 text-center">No products found.</TableCell></TableRow>:visible.map((row:any)=>{const selectedTax=taxDrafts[row.product_id] ?? row.tax_code_id ?? "NONE"; const dirty=selectedTax!==(row.tax_code_id||"NONE"); return <TableRow key={row.product_id}><TableCell>{row.sku}</TableCell><TableCell>{row.product_name}</TableCell><TableCell><Input className="w-36" type="number" min="0" step="0.01" value={drafts[row.product_id] ?? (row.unit_price == null ? "" : String(row.unit_price))} placeholder="Not configured" onChange={e=>setDrafts({...drafts,[row.product_id]:e.target.value})}/></TableCell><TableCell><Can roles={ACTION_ROLES.MANAGE_TAX_CONFIGURATION} fallback={<span className="text-sm">{row.tax_code ? label(row) : "Not classified"}</span>}><div className="flex items-center gap-2"><Select value={selectedTax} onValueChange={value=>setTaxDrafts({...taxDrafts,[row.product_id]:value})}><SelectTrigger className="min-w-52"><SelectValue placeholder="Not classified"/></SelectTrigger><SelectContent><SelectItem value="NONE">Not classified</SelectItem>{codes.map((code:any)=><SelectItem key={code.tax_code_id} value={code.tax_code_id}>{label(code)}</SelectItem>)}</SelectContent></Select>{dirty&&<Button size="sm" disabled={taxMutation.isPending} onClick={()=>taxMutation.mutate({id:row.product_id,taxCodeId:selectedTax === "NONE" ? null : selectedTax})}>{taxMutation.isPending?"Saving...":"Save Tax"}</Button>}</div></Can>{taxMutation.error&&<p className="mt-1 text-xs text-red-600">{getErrorMessage(taxMutation.error)}</p>}</TableCell><TableCell>{profile.currency_code}</TableCell><TableCell>{row.price_active ? <Badge>Active</Badge> : <Badge variant="outline">Not configured</Badge>}</TableCell><TableCell className="text-right"><Can roles={ACTION_ROLES.EDIT_SETUP}><div className="flex justify-end gap-2"><Button size="sm" onClick={()=>{const value=Number(drafts[row.product_id] ?? row.unit_price); if(Number.isFinite(value)&&value>=0){if(row.price_active) onUpdate({id:row.product_id,unit_price:value}); else onCreate({product_id:row.product_id,unit_price:value});}}}>Save Price</Button>{row.price_active&&<Button size="sm" variant="outline" onClick={()=>onDeactivate(row.product_id)}>Deactivate</Button>}</div></Can></TableCell></TableRow>})}</TableBody></Table></div></CardContent></Card>;
}

function policyFormFromResponse(response:any){
  const policy=response?.policy||response?.data||response;
  if(!policy) return null;
  return {
    returns_enabled:Boolean(policy.returns_enabled),
    default_return_window_days:String(policy.default_return_window_days ?? 0),
    proof_of_purchase_required:Boolean(policy.proof_of_purchase_required),
    allow_return_without_receipt:Boolean(policy.allow_return_without_receipt),
    inspection_required:Boolean(policy.inspection_required),
    allow_partial_returns:Boolean(policy.allow_partial_returns),
    allow_damaged_returns:Boolean(policy.allow_damaged_returns),
    allow_change_of_mind_returns:Boolean(policy.allow_change_of_mind_returns),
    refund_to_original_method:Boolean(policy.refund_to_original_method),
    allow_customer_credit:Boolean(policy.allow_customer_credit),
    allow_exchange:Boolean(policy.allow_exchange),
    manager_approval_required:Boolean(policy.manager_approval_required),
    restocking_fee_enabled:Boolean(policy.restocking_fee_enabled),
    restocking_fee_percent:String(policy.restocking_fee_percent ?? 0),
    refund_processing_days:String(policy.refund_processing_days ?? 0),
    policy_notes:policy.policy_notes||"",
    is_active:Boolean(policy.is_active),
  };
}
function ReturnPolicyPanel(){
  const {hasRole}=useAuth();
  const canEdit=hasRole([...ACTION_ROLES.EDIT_SETUP]);
  const query=useQuery({queryKey:["return-policy"],queryFn:getReturnPolicy});
  const [form,setForm]=useState<any>(null);
  const [loadedKey,setLoadedKey]=useState("");
  const [validationError,setValidationError]=useState("");
  const [savedMessage,setSavedMessage]=useState("");
  const policy=policyFormFromResponse(query.data);
  useEffect(()=>{
    const key=policy?.updated_at||policy?.policy_id||"loaded";
    if(policy&&key!==loadedKey){setForm(policy);setLoadedKey(key);setValidationError("");setSavedMessage("");}
  },[query.data,loadedKey]);
  const mutation=useMutation({mutationFn:updateReturnPolicy,onSuccess:async()=>{setSavedMessage("Return & Refund Policy saved.");setValidationError("");await query.refetch();},onError:()=>setSavedMessage("")});
  function update(field:string,value:any){setForm((current:any)=>({...current,[field]:value}));setSavedMessage("");setValidationError("");}
  function save(){
    if(!form) return;
    const windowDays=Number(form.default_return_window_days);
    const feePercent=Number(form.restocking_fee_percent);
    const processingDays=Number(form.refund_processing_days);
    if(!Number.isInteger(windowDays)||windowDays<0){setValidationError("Return window must be a non-negative whole number.");return;}
    if(!Number.isFinite(feePercent)||feePercent<0||feePercent>100){setValidationError("Restocking fee percent must be between 0 and 100.");return;}
    if(!Number.isInteger(processingDays)||processingDays<0){setValidationError("Refund processing days must be a non-negative whole number.");return;}
    mutation.mutate({...form,default_return_window_days:windowDays,restocking_fee_percent:feePercent,refund_processing_days:processingDays});
  }
  return <Card className="rounded-2xl shadow-sm"><CardHeader><CardTitle className="flex items-center gap-2"><RefreshCw className="h-5 w-5"/>Return &amp; Refund Policy</CardTitle><p className="text-sm text-slate-500">Configure the server-enforced rules used when customer returns are reviewed and settled.</p></CardHeader><CardContent>{query.isLoading?<p className="text-sm text-slate-500">Loading return policy...</p>:query.isError?<Alert variant="destructive"><AlertTitle>Return policy unavailable</AlertTitle><AlertDescription>{getErrorMessage(query.error)}</AlertDescription></Alert>:!form?<p className="text-sm text-slate-500">No active return policy is configured.</p>:<><div className="grid gap-4 md:grid-cols-2"><SelectInput label="Returns Enabled" value={String(form.returns_enabled)} onValueChange={v=>update("returns_enabled",v==="true")} options={[["true","Enabled"],["false","Disabled"]]}/><FormInput label="Default Return Window (Days)" type="number" value={form.default_return_window_days} onChange={v=>update("default_return_window_days",v)} disabled={!canEdit}/><SelectInput label="Proof of Purchase Required" value={String(form.proof_of_purchase_required)} onValueChange={v=>update("proof_of_purchase_required",v==="true")} options={[["true","Required"],["false","Not required"]]}/><SelectInput label="Allow Return Without Receipt" value={String(form.allow_return_without_receipt)} onValueChange={v=>update("allow_return_without_receipt",v==="true")} options={[["true","Allowed"],["false","Not allowed"]]}/><SelectInput label="Inspection Required" value={String(form.inspection_required)} onValueChange={v=>update("inspection_required",v==="true")} options={[["true","Required"],["false","Not required"]]}/><SelectInput label="Allow Partial Returns" value={String(form.allow_partial_returns)} onValueChange={v=>update("allow_partial_returns",v==="true")} options={[["true","Allowed"],["false","Not allowed"]]}/><SelectInput label="Allow Damaged Returns" value={String(form.allow_damaged_returns)} onValueChange={v=>update("allow_damaged_returns",v==="true")} options={[["true","Allowed"],["false","Not allowed"]]}/><SelectInput label="Allow Change-of-Mind Returns" value={String(form.allow_change_of_mind_returns)} onValueChange={v=>update("allow_change_of_mind_returns",v==="true")} options={[["true","Allowed"],["false","Not allowed"]]}/><SelectInput label="Refund to Original Payment Method" value={String(form.refund_to_original_method)} onValueChange={v=>update("refund_to_original_method",v==="true")} options={[["true","Allowed"],["false","Not allowed"]]}/><SelectInput label="Allow Customer Credit" value={String(form.allow_customer_credit)} onValueChange={v=>update("allow_customer_credit",v==="true")} options={[["true","Allowed"],["false","Not allowed"]]}/><SelectInput label="Allow Exchange" value={String(form.allow_exchange)} onValueChange={v=>update("allow_exchange",v==="true")} options={[["true","Allowed"],["false","Not allowed"]]}/><SelectInput label="Manager Approval Required" value={String(form.manager_approval_required)} onValueChange={v=>update("manager_approval_required",v==="true")} options={[["true","Required"],["false","Not required"]]}/><SelectInput label="Restocking Fee Enabled" value={String(form.restocking_fee_enabled)} onValueChange={v=>update("restocking_fee_enabled",v==="true")} options={[["true","Enabled"],["false","Disabled"]]}/><FormInput label="Restocking Fee Percent" type="number" value={form.restocking_fee_percent} onChange={v=>update("restocking_fee_percent",v)} disabled={!canEdit||!form.restocking_fee_enabled}/><FormInput label="Refund Processing Days" type="number" value={form.refund_processing_days} onChange={v=>update("refund_processing_days",v)} disabled={!canEdit}/><div className="space-y-2 md:col-span-2"><Label>Policy Notes</Label><Textarea value={form.policy_notes} disabled={!canEdit} onChange={e=>update("policy_notes",e.target.value)} placeholder="Optional notes for staff reviewing returns."/></div></div><p className="mt-4 text-xs text-slate-500">Return Window: number of days after the original sale during which returns are normally allowed. Proof of Purchase: recognized POS sale, delivery, invoice, receipt, or other supporting record. Manager Approval: authorized approval for exceptions outside normal policy.</p>{validationError&&<Alert className="mt-4" variant="destructive"><AlertTitle>Check policy values</AlertTitle><AlertDescription>{validationError}</AlertDescription></Alert>}{mutation.error&&<Alert className="mt-4" variant="destructive"><AlertTitle>Policy save failed</AlertTitle><AlertDescription>{getErrorMessage(mutation.error)}</AlertDescription></Alert>}{savedMessage&&<Alert className="mt-4"><AlertDescription>{savedMessage}</AlertDescription></Alert>}<div className="mt-4 flex items-center justify-between"><p className="text-xs text-slate-500">{canEdit?"Changes affect new return reviews after they are saved.":"View-only access. Contact an administrator or manager to edit this policy."}</p>{canEdit&&<Button onClick={save} disabled={mutation.isPending}>{mutation.isPending?"Saving...":"Save Return Policy"}</Button>}</div></>}</CardContent></Card>;
}
function TaxSettingsPanel(){
  const settingsQuery=useQuery({queryKey:["tax-settings"],queryFn:getTaxSettings});
  const codesQuery=useQuery({queryKey:["tax-codes"],queryFn:getTaxCodes});
  const mutation=useMutation({mutationFn:updateTaxSettings,onSuccess:()=>settingsQuery.refetch()});
  const settings=settingsQuery.data?.data;
  const codes=normalizeArray(codesQuery.data,["tax_codes","data"]);
  const [mode,setMode]=useState("");
  useEffect(()=>{if(settings)setMode(settings.tax_pricing_mode||"TAX_EXCLUSIVE");},[settings]);
  if(settingsQuery.isError)return null;
  return <Card className="rounded-2xl shadow-sm"><CardHeader><CardTitle>VAT / Tax Settings</CardTitle><p className="text-sm text-slate-500">Business-agnostic tax engine with Uganda as the initial configuration. VAT remains disabled until activation checks pass.</p></CardHeader><CardContent><div className="grid gap-4 md:grid-cols-3"><SelectInput label="Tax Engine" value={String(Boolean(settings?.tax_engine_enabled))} onValueChange={v=>mutation.mutate({tax_engine_enabled:v==="true"})} options={[["false","Disabled"],["true","Enabled"]]}/><SelectInput label="VAT Registered" value={String(Boolean(settings?.vat_registered))} onValueChange={v=>mutation.mutate({vat_registered:v==="true"})} options={[["false","No"],["true","Yes"]]}/><SelectInput label="Pricing Mode" value={mode||"TAX_EXCLUSIVE"} onValueChange={v=>{setMode(v);mutation.mutate({tax_pricing_mode:v});}} options={[["TAX_EXCLUSIVE","Tax exclusive"],["TAX_INCLUSIVE","Tax inclusive"]]}/></div><div className="mt-4"><p className="text-sm font-medium">Configured tax codes</p><div className="mt-2 flex flex-wrap gap-2">{codes.map((code:any)=><Badge key={code.tax_code_id} variant="outline">{code.treatment === "STANDARD" ? `Standard Rated — ${code.rate}%` : code.treatment === "ZERO_RATED" ? "Zero Rated — 0%" : code.treatment === "EXEMPT" ? "Exempt" : "Out of Scope"}</Badge>)}</div></div>{mutation.error&&<p className="mt-3 text-sm text-red-600">{getErrorMessage(mutation.error)}</p>}</CardContent></Card>;
}
function TaxReadinessPanel(){
  const query=useQuery({queryKey:["tax-activation-precheck"],queryFn:getTaxActivationPrecheck});
  const checks=query.data?.checks||[]; const failed=checks.filter((check:any)=>!check.is_valid);
  if(query.isLoading||query.isError)return null;
  return <Card className="rounded-2xl border-slate-200 shadow-sm"><CardHeader><CardTitle>Activation readiness</CardTitle><p className="text-sm text-slate-500">The same server precheck is applied before tax settings or the Tax Engine feature can be enabled.</p></CardHeader><CardContent><div className={failed.length?"rounded-lg border border-amber-200 bg-amber-50 p-3":"rounded-lg border border-emerald-200 bg-emerald-50 p-3"}><p className="font-medium">{failed.length?"Blocked — resolve these items before activation":"Ready for activation"}</p>{failed.length>0&&<ul className="mt-2 list-disc pl-5 text-sm">{failed.map((check:any)=><li key={check.check_code}>{check.message}</li>)}</ul>}</div>{failed.some((check:any)=>check.check_code==="PRODUCT_CLASSIFICATION")&&<Button className="mt-3" variant="outline" onClick={()=>document.getElementById("product-tax-classification")?.scrollIntoView({behavior:"smooth"})}>Open Product Tax Classification</Button>}</CardContent></Card>;
}
function TaxRateManagementPanel(){
  const query=useQuery({queryKey:["tax-rate-management"],queryFn:getTaxCodes});
  const createMutation=useMutation({mutationFn:createTaxCode,onSuccess:()=>query.refetch()});
  const updateMutation=useMutation({mutationFn:({id,payload}:{id:string;payload:any})=>updateTaxCode(id,payload),onSuccess:()=>query.refetch()});
  const [form,setForm]=useState({code:"STANDARD",name:"Standard Rated VAT",treatment:"STANDARD",rate:"18",effective_from:new Date().toISOString().slice(0,10),effective_to:""});
  const codes=normalizeArray(query.data,["tax_codes","data"]);
  return <Card className="rounded-2xl shadow-sm"><CardHeader><CardTitle>Tax Rate Management</CardTitle><p className="text-sm text-slate-500">Administrator-only effective-dated rates. New periods are added as new tax-code rows so posted snapshots remain unchanged.</p></CardHeader><CardContent><Can roles={ACTION_ROLES.MANAGE_TAX_CONFIGURATION}><div className="grid gap-3 rounded-lg border bg-slate-50 p-3 md:grid-cols-6"><Input aria-label="Tax code" value={form.code} onChange={e=>setForm({...form,code:e.target.value.toUpperCase()})} placeholder="Tax code"/><Input aria-label="Tax name" value={form.name} onChange={e=>setForm({...form,name:e.target.value})} placeholder="Name"/><Select value={form.treatment} onValueChange={v=>setForm({...form,treatment:v,rate:v==="ZERO_RATED"?"0":form.rate})}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{["STANDARD","ZERO_RATED","EXEMPT","OUT_OF_SCOPE"].map(v=><SelectItem key={v} value={v}>{v}</SelectItem>)}</SelectContent></Select><Input aria-label="Rate" type="number" min="0" max="100" step="0.01" value={form.rate} disabled={form.treatment==="EXEMPT"||form.treatment==="OUT_OF_SCOPE"} onChange={e=>setForm({...form,rate:e.target.value})} placeholder="Rate %"/><Input aria-label="Effective from" type="date" value={form.effective_from} onChange={e=>setForm({...form,effective_from:e.target.value})}/><Button disabled={createMutation.isPending} onClick={()=>createMutation.mutate({...form,rate:Number(form.rate||0),effective_to:form.effective_to||null})}>Add Rate Period</Button></div></Can><div className="mt-4 overflow-x-auto rounded-xl border"><Table><TableHeader><TableRow><TableHead>Tax Code</TableHead><TableHead>Name</TableHead><TableHead>Treatment</TableHead><TableHead>Rate</TableHead><TableHead>Effective From</TableHead><TableHead>Effective To</TableHead><TableHead>Status</TableHead><TableHead className="text-right">Action</TableHead></TableRow></TableHeader><TableBody>{codes.map((code:any)=><TableRow key={code.tax_code_id}><TableCell>{code.code}</TableCell><TableCell>{code.name}</TableCell><TableCell>{code.treatment}</TableCell><TableCell>{["EXEMPT","OUT_OF_SCOPE"].includes(code.treatment)?"—":`${code.rate}%`}</TableCell><TableCell>{String(code.effective_from).slice(0,10)}</TableCell><TableCell><Input className="w-36" type="date" defaultValue={code.effective_to?String(code.effective_to).slice(0,10):""} onBlur={e=>{const value=e.target.value||null;if(value!== (code.effective_to?String(code.effective_to).slice(0,10):null))updateMutation.mutate({id:code.tax_code_id,payload:{effective_to:value}})}}/></TableCell><TableCell>{code.is_active?<Badge>Active</Badge>:<Badge variant="outline">Inactive</Badge>}</TableCell><TableCell className="text-right"><Can roles={ACTION_ROLES.MANAGE_TAX_CONFIGURATION}><Button size="sm" variant="outline" onClick={()=>updateMutation.mutate({id:code.tax_code_id,payload:{is_active:!code.is_active}})}>{code.is_active?"Deactivate":"Activate"}</Button></Can></TableCell></TableRow>)}</TableBody></Table></div>{(createMutation.error||updateMutation.error)&&<p className="mt-3 text-sm text-red-600">{getErrorMessage(createMutation.error||updateMutation.error)}</p>}</CardContent></Card>;
}
function BusinessFeaturesPanel(props:{query:any;mutation:any}){return <><ReturnPolicyPanel/><TaxSettingsPanel/><TaxRateManagementPanel/><TaxReadinessPanel/><ProductTaxAssignmentPanel/><ExistingBusinessFeaturesPanel {...props}/></>;}
function ProductTaxAssignmentPanel(){
  const queryClient=useQueryClient();
  const productsQuery=useQuery({queryKey:["tax-product-classification"],queryFn:getProducts});
  const codesQuery=useQuery({queryKey:["tax-product-codes"],queryFn:getTaxCodes});
  const mutation=useMutation({mutationFn:({id,payload}:{id:string;payload:any})=>updateProduct(id,payload),onSuccess:async()=>{await productsQuery.refetch();await queryClient.invalidateQueries({queryKey:["tax-activation-precheck"]});}});
  const products=normalizeArray(productsQuery.data,["products","data"]); const codes=normalizeArray(codesQuery.data,["tax_codes","data"]);
  if(productsQuery.isError||codesQuery.isError)return null;
  return <Card className="rounded-2xl shadow-sm"><CardHeader><CardTitle>Product Tax Classification</CardTitle><p className="text-sm text-slate-500">Assign a configured treatment before VAT activation. Existing products remain unclassified until selected.</p></CardHeader><CardContent><div className="space-y-2">{products.slice(0,100).map((product:any)=><div key={product.product_id} className="grid items-center gap-3 rounded-lg border p-3 md:grid-cols-[1fr_240px]"><div><p className="font-medium">{product.sku} — {product.product_name}</p><p className="text-xs text-slate-500">{product.tax_treatment ? `${product.tax_treatment} ${product.tax_rate ?? 0}%` : "Unclassified"}</p></div><Select value={product.tax_code_id || "NONE"} onValueChange={value=>{const code=value==="NONE"?null:codes.find((item:any)=>item.tax_code_id===value); mutation.mutate({id:product.product_id,payload:{...product,category_code:undefined,category_name:undefined,tax_code_id:code?.tax_code_id||null}});}}><SelectTrigger><SelectValue placeholder="Unclassified"/></SelectTrigger><SelectContent><SelectItem value="NONE">Unclassified</SelectItem>{codes.filter((code:any)=>code.is_active!==false).map((code:any)=><SelectItem key={code.tax_code_id} value={code.tax_code_id}>{code.treatment === "STANDARD" ? `Standard Rated — ${code.rate}%` : code.treatment === "ZERO_RATED" ? "Zero Rated — 0%" : code.treatment === "EXEMPT" ? "Exempt" : "Out of Scope"}</SelectItem>)}</SelectContent></Select></div>)}</div>{mutation.error&&<p className="mt-3 text-sm text-red-600">{getErrorMessage(mutation.error)}</p>}</CardContent></Card>;
}
function ExistingBusinessFeaturesPanel({query,mutation}:{query:any;mutation:any}){
  const labels:any={sales:"Sales",purchasing:"Purchasing",inventory:"Inventory",cleaning:"Cleaning Batches",finance:"Finance",reports:"Reports",pos:"POS / Quick Sale",barcode:"Barcode Scanning"};
  const definitions=query.data?.definitions || Object.keys(query.features).map(feature_code=>({feature_code,feature_name:labels[feature_code],feature_group:feature_code==="barcode"?"FUTURE":"CURRENT",description:null,is_enabled:query.features[feature_code]}));
  const update=(feature_code:string,is_enabled:boolean)=>mutation.mutate({features:{[feature_code]:is_enabled}});
  const profile=useBusinessProfile().data;
  const pricesQuery=useQuery({queryKey:["setup-pos-prices"],queryFn:getPosPrices,enabled:query.hasFeature("pos")});
  const barcodesQuery=useQuery({queryKey:["setup-pos-barcodes"],queryFn:getPosBarcodes,enabled:query.hasFeature("barcode")});
  const productsForBarcodeQuery=useQuery({queryKey:["setup-barcode-products"],queryFn:getProducts});
  const createPriceMutation=useMutation({mutationFn:createPosPrice,onSuccess:async()=>{await pricesQuery.refetch();}});
  const updatePriceMutation=useMutation({mutationFn:({id,unit_price}:{id:string;unit_price:number})=>updatePosPrice(id,{unit_price}),onSuccess:async()=>{await pricesQuery.refetch();}});
  const deactivatePriceMutation=useMutation({mutationFn:deactivatePosPrice,onSuccess:async()=>{await pricesQuery.refetch();}});
  const createBarcodeMutation=useMutation({mutationFn:createPosBarcode,onSuccess:()=>barcodesQuery.refetch()});
  const deactivateBarcodeMutation=useMutation({mutationFn:deactivatePosBarcode,onSuccess:()=>barcodesQuery.refetch()});
  return <><Card className="rounded-2xl shadow-sm"><CardHeader><CardTitle>Business Features</CardTitle><p className="text-sm text-slate-500">Control which platform capabilities this business uses. User permissions still apply independently.</p></CardHeader><CardContent className="space-y-5"><div><p className="mb-2 text-xs font-semibold uppercase tracking-wide text-slate-500">Current Features</p><div className="grid gap-3 md:grid-cols-2">{definitions.filter((d:any)=>d.feature_group!=="FUTURE").map((feature:any)=><FeatureToggle key={feature.feature_code} feature={feature} enabled={query.features[feature.feature_code]} onChange={update}/>)}</div></div><div><p className="mb-2 text-xs font-semibold uppercase tracking-wide text-slate-500">Future / Not Yet Implemented</p><div className="grid gap-3 md:grid-cols-2">{definitions.filter((d:any)=>d.feature_group==="FUTURE").map((feature:any)=><FeatureToggle key={feature.feature_code} feature={feature} enabled={false} onChange={update} disabled/>)}</div></div></CardContent></Card><ProductPricesPanel query={pricesQuery} profile={profile} onCreate={createPriceMutation.mutate} onUpdate={updatePriceMutation.mutate} onDeactivate={deactivatePriceMutation.mutate}/><BarcodeAdminPanel query={barcodesQuery} products={normalizeArray(productsForBarcodeQuery.data,["products","data"])} onCreate={createBarcodeMutation.mutate} onDeactivate={deactivateBarcodeMutation.mutate}/></>;
}
function BarcodeAdminPanel({query,products,onCreate,onDeactivate}:{query:any;products:any[];onCreate:(payload:any)=>void;onDeactivate:(id:string)=>void}){const [productId,setProductId]=useState("");const [barcode,setBarcode]=useState("");const rows=query.data?.barcodes||query.data?.data||[];return <Card className="rounded-2xl shadow-sm"><CardHeader><CardTitle>Product Barcodes</CardTitle><p className="text-sm text-slate-500">Assign unique barcodes for keyboard-wedge scanner lookup.</p></CardHeader><CardContent><div className="grid gap-2 md:grid-cols-[1fr_1fr_auto]"><select className="rounded-lg border px-3 py-2" value={productId} onChange={e=>setProductId(e.target.value)}><option value="">Select product</option>{products.map(p=><option key={p.product_id} value={p.product_id}>{p.sku} — {p.product_name}</option>)}</select><Input placeholder="Barcode" value={barcode} onChange={e=>setBarcode(e.target.value)}/><Button disabled={!productId||!barcode.trim()} onClick={()=>{onCreate({product_id:productId,barcode:barcode.trim()});setBarcode("")}}>Assign</Button></div><div className="mt-4 overflow-x-auto rounded-xl border"><Table><TableHeader><TableRow><TableHead>Barcode</TableHead><TableHead>SKU</TableHead><TableHead>Product</TableHead><TableHead>Status</TableHead><TableHead /></TableRow></TableHeader><TableBody>{rows.map((row:any)=><TableRow key={row.barcode_id}><TableCell>{row.barcode}</TableCell><TableCell>{row.sku}</TableCell><TableCell>{row.product_name}</TableCell><TableCell>{row.is_active?"Active":"Inactive"}</TableCell><TableCell className="text-right">{row.is_active&&<Button size="sm" variant="outline" onClick={()=>onDeactivate(row.barcode_id)}>Deactivate</Button>}</TableCell></TableRow>)}</TableBody></Table></div></CardContent></Card>}
function FeatureToggle({feature,enabled,onChange,disabled=false}:{feature:any;enabled:boolean;onChange:(code:string,value:boolean)=>void;disabled?:boolean}){return <div className="flex items-center justify-between rounded-xl border bg-white px-4 py-3"><div><p className="font-medium text-slate-900">{feature.feature_name}</p><p className="text-xs text-slate-500">{disabled?"Coming later":"Business capability"}</p></div><Can roles={ACTION_ROLES.EDIT_SETUP}><Button variant={enabled?"default":"outline"} size="sm" disabled={disabled} onClick={()=>onChange(feature.feature_code,!enabled)}>{disabled?"Coming later":enabled?"Enabled":"Disabled"}</Button></Can></div>}
function SetupTab({active,icon:Icon,title,count,onClick}:{active:boolean;icon:ElementType;title:string;count:number;onClick:()=>void}){return <button type="button" onClick={onClick} className={["rounded-2xl border p-5 text-left shadow-sm transition",active?"border-slate-900 bg-slate-900 text-white":"bg-white hover:bg-slate-50"].join(" ")}><div className="flex items-center justify-between"><Icon className="h-5 w-5"/><Badge variant={active?"secondary":"outline"}>{count}</Badge></div><p className="mt-4 font-semibold">{title}</p></button>;}
function FormInput({label,value,onChange,type="text",disabled=false}:{label:string;value:string;onChange:(v:string)=>void;type?:string;disabled?:boolean}){return <div className="space-y-2"><Label>{label}</Label><Input type={type} value={value} disabled={disabled} onChange={e=>onChange(e.target.value)}/></div>;}
function SelectInput({label,value,onValueChange,options}:{label:string;value:string;onValueChange:(v:string)=>void;options:(string|[string,string])[]}){return <div className="space-y-2"><Label>{label}</Label><Select value={value} onValueChange={onValueChange}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{options.map(o=>{const v=Array.isArray(o)?o[0]:o; const l=Array.isArray(o)?o[1]:o; return <SelectItem key={v} value={v}>{l}</SelectItem>;})}</SelectContent></Select></div>;}
function PartyForm({form,setForm}:{form:any;setForm:(f:any)=>void}){return <div className="grid gap-4 md:grid-cols-2"><SelectInput label="Party Type" value={form.party_type} onValueChange={v=>setForm({...form,party_type:v})} options={["CUSTOMER","SUPPLIER","BOTH","STAFF"]}/><FormInput label="Party Name" value={form.party_name} onChange={v=>setForm({...form,party_name:v})}/><FormInput label="Phone" value={form.phone} onChange={v=>setForm({...form,phone:v})}/><FormInput label="Email" value={form.email} onChange={v=>setForm({...form,email:v})}/><FormInput label="Tax ID" value={form.tax_id} onChange={v=>setForm({...form,tax_id:v})}/><SelectInput label="Status" value={form.is_active} onValueChange={v=>setForm({...form,is_active:v})} options={[["true","Active"],["false","Inactive"]]}/><div className="space-y-2 md:col-span-2"><Label>Billing Address</Label><Textarea value={form.billing_address} onChange={e=>setForm({...form,billing_address:e.target.value})}/></div><div className="space-y-2 md:col-span-2"><Label>Shipping Address</Label><Textarea value={form.shipping_address} onChange={e=>setForm({...form,shipping_address:e.target.value})}/></div></div>;}
function LocationForm({form,setForm}:{form:any;setForm:(f:any)=>void}){return <div className="grid gap-4 md:grid-cols-2"><FormInput label="Location Code" value={form.location_code} disabled={form.is_system} onChange={v=>setForm({...form,location_code:v})}/><FormInput label="Location Name" value={form.location_name} onChange={v=>setForm({...form,location_name:v})}/><SelectInput label="Type" value={form.location_type} onValueChange={v=>setForm({...form,location_type:v})} options={["HEAD_OFFICE","BRANCH","SHOP","WAREHOUSE","STOCK_ROOM","PRODUCTION","QUARANTINE","DAMAGED","TRANSIT","VIRTUAL"]}/><SelectInput label="Status" value={form.is_active} onValueChange={v=>setForm({...form,is_active:v})} options={[["true","Active"],["false","Inactive"]]}/><SelectInput label="Saleable stock" value={form.is_saleable} onValueChange={v=>setForm({...form,is_saleable:v})} options={[["true","Yes"],["false","No"]]}/><SelectInput label="Holds stock" value={form.is_stock_holding} onValueChange={v=>setForm({...form,is_stock_holding:v})} options={[["true","Yes"],["false","No"]]}/><FormInput label="Address" value={form.address} onChange={v=>setForm({...form,address:v})}/><FormInput label="Phone" value={form.phone} onChange={v=>setForm({...form,phone:v})}/><FormInput label="Email" value={form.email} onChange={v=>setForm({...form,email:v})}/><FormInput label="Notes" value={form.notes} onChange={v=>setForm({...form,notes:v})}/></div>;}
function UomForm({form,setForm,editing}:{form:any;setForm:(f:any)=>void;editing:boolean}){return <div className="grid gap-4"><FormInput label="UOM Code" value={form.uom_code} disabled={editing} onChange={v=>setForm({...form,uom_code:v})}/><FormInput label="UOM Name" value={form.uom_name} onChange={v=>setForm({...form,uom_name:v})}/></div>;}
function ProductForm({form,setForm,uoms,categories = normalizeArray(useQuery({queryKey:["setup-product-categories"],queryFn:getProductCategories}).data,["categories","data"])}:{form:any;setForm:(f:any)=>void;uoms:AnyRecord[];categories?:AnyRecord[]}){return <div className="grid gap-4 md:grid-cols-2"><FormInput label="SKU" value={form.sku} onChange={v=>setForm({...form,sku:v})}/><FormInput label="Product Name" value={form.product_name} onChange={v=>setForm({...form,product_name:v})}/><div className="md:col-span-2"><Label>Description</Label><Textarea value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/></div><SelectInput label="Product Type" value={form.product_type} onValueChange={v=>setForm({...form,product_type:v})} options={["RAW","FINISHED","PACKAGING","SERVICE"]}/><div className="space-y-2"><Label>UOM</Label><Select value={form.uom_code} onValueChange={v=>setForm({...form,uom_code:v})}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{uoms.map(u=><SelectItem key={u.uom_code} value={u.uom_code}>{u.uom_code} - {u.uom_name}</SelectItem>)}</SelectContent></Select></div><div className="space-y-2"><Label>Category</Label><Select value={form.category_id || "NONE"} onValueChange={v=>setForm({...form,category_id:v === "NONE" ? "" : v})}><SelectTrigger><SelectValue placeholder="No category"/></SelectTrigger><SelectContent><SelectItem value="NONE">No category</SelectItem>{categories.filter(c=>c.is_active!==false).map(c=><SelectItem key={c.category_id} value={c.category_id}>{c.category_code} - {c.category_name}</SelectItem>)}</SelectContent></Select></div><FormInput label="Lot Prefix" value={form.lot_prefix} onChange={v=>setForm({...form,lot_prefix:v})}/><FormInput label="Shelf Life Days" type="number" value={form.shelf_life_days} onChange={v=>setForm({...form,shelf_life_days:v})}/><SelectInput label="Purchasable" value={form.is_purchasable} onValueChange={v=>setForm({...form,is_purchasable:v})} options={[["true","Yes"],["false","No"]]}/><SelectInput label="Stock Item" value={form.is_stock_item} onValueChange={v=>setForm({...form,is_stock_item:v})} options={[["true","Yes"],["false","No"]]}/><SelectInput label="Track Lots" value={form.track_lots} onValueChange={v=>setForm({...form,track_lots:v})} options={[["true","Yes"],["false","No"]]}/><SelectInput label="Track Expiry" value={form.track_expiry} onValueChange={v=>setForm({...form,track_expiry:v})} options={[["true","Yes"],["false","No"]]}/><SelectInput label="Saleable" value={form.is_saleable} onValueChange={v=>setForm({...form,is_saleable:v})} options={[["true","Yes"],["false","No"]]}/><SelectInput label="Status" value={form.is_active} onValueChange={v=>setForm({...form,is_active:v})} options={[["true","Active"],["false","Inactive"]]}/></div>;}
function ActionCell({row,onOpen,onDelete}:{row:AnyRecord;onOpen:(r:AnyRecord)=>void;onDelete:(r:AnyRecord)=>void}){return <div className="flex justify-end gap-2"><Can roles={ACTION_ROLES.EDIT_SETUP}><Button variant="outline" size="sm" onClick={(e)=>{e.stopPropagation();onOpen(row);}}><Edit className="mr-2 h-4 w-4"/>Edit</Button></Can><Can roles={ACTION_ROLES.DELETE}><Button variant="destructive" size="sm" onClick={(e)=>{e.stopPropagation();onDelete(row);}}><Trash2 className="mr-2 h-4 w-4"/>Delete</Button></Can></div>;}
function SetupTable({tab,rows,onOpen,onDelete}:{tab:TabKey;rows:AnyRecord[];onOpen:(r:AnyRecord)=>void;onDelete:(r:AnyRecord)=>void}){const headers=tab==="parties"?["Type","Name","Phone","Email","Active","Action"]:tab==="locations"?["Code","Name","Active","Created At","Action"]:tab==="uoms"?["Code","Name","Action"]:["SKU","Product","Type","UOM","Lots","Expiry","Saleable","Active","Action"]; const render=(row:AnyRecord):(ReactNode[])=> tab==="parties"?[row.party_type,row.party_name,row.phone||"-",row.email||"-",boolText(row.is_active),<ActionCell key="a" row={row} onOpen={onOpen} onDelete={onDelete}/>]:tab==="locations"?[row.location_code,row.location_name,boolText(row.is_active),formatDateTime(row.created_at),<ActionCell key="a" row={row} onOpen={onOpen} onDelete={onDelete}/>]:tab==="uoms"?[row.uom_code,row.uom_name,<ActionCell key="a" row={row} onOpen={onOpen} onDelete={onDelete}/>]:[row.sku,row.product_name,row.product_type,row.uom_code,boolText(row.track_lots),boolText(row.track_expiry),boolText(row.is_saleable),boolText(row.is_active),<ActionCell key="a" row={row} onOpen={onOpen} onDelete={onDelete}/>]; return <div className="overflow-x-auto rounded-xl border"><Table><TableHeader><TableRow>{headers.map(h=><TableHead key={h} className={h==="Action"?"text-right":""}>{h}</TableHead>)}</TableRow></TableHeader><TableBody>{rows.length===0?<TableRow><TableCell colSpan={headers.length} className="h-24 text-center">No records found.</TableCell></TableRow>:rows.map((row,i)=><TableRow key={i} className="cursor-pointer" onDoubleClick={()=>onOpen(row)} title="Double-click to open/edit">{render(row).map((cell,j)=><TableCell key={j} className={headers[j]==="Action"?"text-right":""}>{cell}</TableCell>)}</TableRow>)}</TableBody></Table></div>;}
